 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    marker=next(( (i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x==2),(0,0))
    mr,mc=marker
    stripes=[i for i,row in enumerate(grid) if 8 in row]
    # Extend from the marker to the first patterned row through its gap, then
    # link openings of successive patterned rows across the intervening space.
    active={mc}
    for idx,r in enumerate(stripes):
        gaps=[j for j,v in enumerate(grid[r]) if v==0]
        if not gaps: continue
        if idx==0:
            selected={min(gaps,key=lambda j:abs(j-mc))}
            # initial span links the ray's axis to the opening
            lo=min(mc,*selected); hi=max(mc,*selected)
            for j in range(lo,hi+1):
                if grid[r-1][j]==0 and r-1>=0: out[r-1][j]=2
        else:
            selected=set(gaps)
        for j in selected: out[r][j]=2
        if idx+1<len(stripes):
            nr=stripes[idx+1]
            ng=[j for j,v in enumerate(grid[nr]) if v==0]
            if ng:
                lo=min(gaps+ng); hi=max(gaps+ng)
                for rr in range(r+1,nr):
                    for j in range(lo,hi+1):
                        if grid[rr][j]==0: out[rr][j]=2
                for j in ng: out[nr][j]=2
    # Continue final connected openings vertically below the last band.
    if stripes:
        last=stripes[-1]; gs=[j for j,v in enumerate(grid[last]) if v==0]
        if gs:
            for rr in range(last+1,h):
                for j in gs:
                    if grid[rr][j]==0: out[rr][j]=2
    return out
