 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-2/play/users/u062/system/state/workspace/programs/task-4bba16f3.py",
 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    mr,mc=next(((i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x==2),(0,0))
    stripes=[i for i,row in enumerate(grid) if 8 in row]
    if not stripes: return out
    # Follow the ray through successive openings in each horizontal 8-barrier.
    lane=mc
    for idx,r in enumerate(stripes):
        gaps=[j for j,v in enumerate(grid[r]) if v==0]
        if not gaps: continue
        gap=min(gaps,key=lambda j:abs(j-lane))
        if idx==0:
            # approach first opening vertically, with a lateral connector on
            # the blank row directly above the barrier
            for rr in range(mr+1,r-1):
                if grid[rr][lane]==0: out[rr][lane]=2
            for j in range(min(lane,gap),max(lane,gap)+1):
                if grid[r-1][j]==0: out[r-1][j]=2
        else:
            prev=stripes[idx-1]
            for rr in range(prev+1,r):
                for j in range(min(lane,gap),max(lane,gap)+1):
                    if grid[rr][j]==0: out[rr][j]=2
        out[r][gap]=2
        lane=gap
    last=stripes[-1]
    for rr in range(last+1,h):
        if grid[rr][lane]==0: out[rr][lane]=2
    return out
